<?php
require_once __DIR__.'/../config.php';
$me=require_admin();
$users=data_load('users.json');$logs=array_reverse(data_load('logs.json'));$threads=data_load('threads.json');
if($_SERVER['REQUEST_METHOD']==='POST'){
 check_csrf();$id=(int)($_POST['user_id']??0);$action=$_POST['mod_action']??'ban_both';$reason=clean_text($_POST['reason']??'Нарушение правил',300);$days=(int)($_POST['days']??7);
 foreach($users as &$target){if((int)$target['id']!==$id)continue;if(($target['role']??'')==='owner')break;$until=$days===0?'permanent':date('c',time()+$days*86400);if($action==='unban'){$target['ban']=null;$target['banned_until']=null;$target['ban_reason']='';log_action('Снятие бана',$target['username'],$reason);}else{if(in_array($action,['ban','ban_both'],true)){$target['ban']=['active'=>true,'until'=>$until,'reason'=>$reason];$target['banned_until']=$until;$target['ban_reason']=$reason;}if(in_array($action,['ban_ip','ban_both'],true)){$bans=data_load('bans.json');$bans[]=['id'=>next_id($bans),'type'=>'ip','value'=>$target['ip']??'','until'=>$until,'reason'=>$reason,'user_id'=>$id];data_save('bans.json',$bans);}log_action($action,$target['username'],$reason);}break;}
 unset($target);data_save('users.json',$users);header('Location:index.php');exit;
}
$title='Админ-панель — GREFFRLEND';include __DIR__.'/../includes/header.php';
?>
